import {projects,profile} from './projects.js';
import {contentDefaults,cleanContent} from './content-schema.js';
const originals=projects.map(p=>structuredClone(p));
let content=cleanContent(),revision=null,canEdit=false,loadError='';
export const getContent=()=>structuredClone(content);
export const contentAccess=()=>({canEdit,loadError});
export function previewContent(value){content=cleanContent(value);for(const [i,p] of projects.entries()){delete p.liveUrl;Object.assign(p,originals[i]);const c=content.projects[p.id];if(c){for(const key of ['title','subtitle','description','image'])if(c[key])p[key]=c[key];if(c.link)p.liveUrl=c.link}}profile.introduction=content.introduction;applyContent();window.dispatchEvent(new CustomEvent('museum-content',{detail:getContent()}));}
export function applyContent(){const c=content;const set=(s,v)=>{const el=document.querySelector(s);if(el)el.textContent=v};set('.brand',c.brand);set('.intro .eyebrow',c.eyebrow);set('#page-title',c.title);set('.intro-copy',c.description);set('#about-copy',c.introduction);set('.site-footer>span',c.footer);document.documentElement.style.setProperty('--museum-accent',c.accent);document.documentElement.style.setProperty('--museum-room',c.room);}
export async function loadContent(){try{const r=await fetch('/api/content',{cache:'no-store',signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error();const data=await r.json();revision=data.revision;canEdit=data.canEdit;previewContent(data.content||contentDefaults)}catch{loadError='전시 설정을 불러오지 못했습니다. 기본 전시를 보여드립니다.';applyContent()}}
export async function saveContent(value){const next=cleanContent(value);const r=await fetch('/api/content',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:next,revision})});const data=await r.json();if(!r.ok)throw Error(data.error||'저장하지 못했습니다.');revision=data.revision;previewContent(data.content);return data;}
export async function uploadImage(file){if(!file||file.size>5*1024*1024)throw Error('5MB 이하 이미지를 선택해 주세요.');if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw Error('PNG, JPG, WebP, GIF 파일을 선택해 주세요.');const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>25000000){bitmap.close();throw Error('이미지 해상도는 2,500만 화소 이하로 선택해 주세요.')}bitmap.close();const r=await fetch('/api/upload',{method:'POST',headers:{'Content-Type':file.type},body:file});const data=await r.json();if(!r.ok)throw Error(data.error);return data.url;}
